from save_review import save
save(1301,{2:'等离子炮又称重型等离子枪，是等离子枪的放大版本。',5:'由于体积庞大、供能需求极高，等离子炮主要安装于载具，但星际战士的破坏者小队也会携行使用。它射出炽亮的过热等离子团，命中后与目标物质反应，形成如微型太阳般沸腾的核能球，因此也俗称“日光枪”。',20:'太阳军“太阳烈焰”型——采用双巨核设计，在泰拉制造，曾于大远征和荷鲁斯之乱期间配发给阿斯塔特军团。',24:'首要型——由涅克罗蒙达的凡·萨尔家族使用，另有名为“超新星”的改型。',26:"Primus Pattern 'Supernova' Variant 首要型“超新星”改型",28:'苏利斯亚型——又称日光枪，由涅克罗蒙达的埃舍尔家族使用。'},notes={20:'magnacore沿前文Magnacore巨核，不是magnetic core磁芯。',24:'Primus沿1299首要型；并非Primaris原铸。'},terms=[('Plasma Cannon','等离子炮'),('Heavy Plasma Gun','重型等离子枪'),('Sol Militaris Helion Fire Pattern','太阳军太阳烈焰型'),('Sulis Sub-Type','苏利斯亚型'),('Primus Pattern','首要型')])
save(1302,{2:'行刑者加农炮是一种可追溯至大远征时代的帝国等离子武器，M41的战场上已几乎看不到它。它比现代等离子枪更可靠，因为帝国初创时的人类对等离子技术掌握得更充分。'},terms=[('Executioner Cannon','行刑者加农炮')],title='行刑者加农炮 Executioner Cannon')
save(1303,{2:'等离子根除炮是阿斯特赖俄斯超重型坦克使用的一种等离子武器，常安装于侧炮座，替代激光撕裂炮。',4:'Plasma Eradicator 等离子根除炮'},terms=[('Plasma Eradicator','等离子根除炮'),('Las-Ripper','激光撕裂炮')])
save(1304,{2:'等离子爆破炮是帝国使用的重型等离子武器，通常用于对抗泰坦，其过热能量足以摧毁战场上的大片区域。它可安装于各种帝国泰坦、部分超重型坦克及其他载具。',5:'等离子爆破炮采用与等离子手枪、等离子枪和等离子炮相同的技术，只是规模大得多。承载它的大型战争机器能安装更高效的冷却系统，因此不像小型武器那样容易过热。不过，它产生的大量废热和热冲击波仍会危及附近人员，在友军周围开火时必须谨慎。其威力惊人，几次射击便能击溃泰坦级虚空盾，将装甲熔成残渣。因此，需要在战地进行改装时，它可作为火山炮的替代武器；只是射程较短，必须更接近目标。安装于泰坦时，它能直接从泰坦的等离子反应堆取能，因而不受常规弹药数量限制。较小的载具无法搭载反应堆，只能使用大型光子燃料单元，射击次数也较少。即使如此，它仍比涡轮激光破坏炮等同级武器更易维护、补给，很适合长时间作战。它还可选择单次全功率射击或连续发射多团威力较低的等离子体，以应对不同类型的敌人。',7:'等离子爆破炮可安装于战犬级侦察泰坦的臂部挂点，以及掠夺者级、战将级战斗泰坦的背甲挂点；更强大的帝皇级泰坦也可在背甲上搭载。它还是风暴刃和马卡里乌斯“欧米伽”坦克的主武器，也曾装备于现已过时的帝国锤刃战斗轰炸机。',11:'安装于火星型战犬级侦察泰坦。',19:'欧米伽型是常见瑞扎型的一种改型，由探索者瓦斯利斯特尔·胡姆纳尔在M39重新发现。然而，机械修会内部的教义争论使其现场试验和开发搁置了数百年。它采用更紧凑的发电装置与力场熔炉，便于制造和维修，也能安装于马卡里乌斯重型坦克等较小的战争机器上；代价是发热更多，稳定性低于瑞扎型。总体而言，它仍利大于弊，目前在卢修斯、地狱恩典和戴纳克斯主星制造。'},notes={5:'engines在此指承载武器的战争机器，不是发动机；不限射击次数沿泰坦直接取能的设定理解。',19:'force crucible暂译力场熔炉；原文技术部件定义有限，不扩写结构。'},terms=[('Plasma Blastgun','等离子爆破炮'),('Hammerblade Fighter-Bomber','锤刃战斗轰炸机'),("Vaslistle Hum’nal",'瓦斯利斯特尔·胡姆纳尔'),('Hellgrace','地狱恩典'),('Dynax Primus','戴纳克斯主星'),('Omega Pattern Plasma Blastgun','欧米伽型等离子爆破炮')])
save(1305,{2:'等离子毁灭炮是一种安装于黎曼鲁斯处决者和迪莫斯型处刑者掠食者战车的等离子武器。',4:'Plasma Destroyer 等离子毁灭炮',7:'它射出的等离子团炽热如太阳，能焚毁血肉、轰碎动力盔甲，尤其适合攻城和远距离猎杀坦克。然而，这种武器极不稳定，也十分危险；在许多人看来，只有莽勇乃至疯狂之人才会操作它。瑞扎是唯一掌握制造技术的铸造世界。武器以光子燃料单元供能，由其产生庞大却难以约束的能量。不少指挥官抱怨，燃料单元无法支持长时间战斗，在激烈交火中更换又过于耗时。搭载它的载具通常设有隔热板、应急排气口和冷却液箱等安全装置；即便如此，约束场若发生灾难性故障，仍可能毁掉整辆载具。'},notes={7:'temperamental指性能不稳定，不是高级气质；containment field为约束场。'},terms=[('Plasma Destroyer','等离子毁灭炮')],title='等离子毁灭炮 Plasma Destroyer')
save(1306,{2:'狱火等离子大炮是帝国在大远征和荷鲁斯之乱期间使用的重型等离子武器，通常装备于无畏机甲。',4:'Deredeo Pattern Dreadnought with Hellfire Plasma Cannonade 装备狱火等离子大炮的德雷都型无畏机甲'},terms=[('Hellfire Plasma Cannonade','狱火等离子大炮')],title='狱火等离子大炮 Hellfire Plasma Cannonade')
save(1307,{6:'西卡然欧米伽的等离子阵列能将不稳定的高能等离子体聚焦，以高压流束射出，汽化外层装甲，烧穿敌方坦克的防护。这种等离子技术的运用颇为粗糙，很少能像激光炮等常见的同级武器那样干净利落地摧毁目标，却终究能将最坚固的敌方载具熔成废墟。'},notes={6:'of weapons修饰破坏效果，并非“摧毁相同口径的武器”。volatile在此指等离子体不稳定，不是易挥发。'},terms=[('Omega Plasma Array','欧米伽等离子阵列')])
save(1308,{2:'激光武器在英文中称为 Laser Weapons，也简称 Las Weapons，涵盖帝国及部分异形种族使用的各类激光兵器。帝国的激光技术相对简单，多数世界都具备制造所需的技术基础。这类武器价格低廉、易于维护，可靠性在帝国兵器中名列前茅。其中，激光枪大量配发给帝国卫队，在多数帝国世界也很容易取得。',5:'激光武器发射高度聚焦的高能光束，使目标表面温度骤变并汽化，产生小规模爆炸。光束只持续极短时间，形成灼亮闪光，并因空气电离发出独特的脆响或爆裂声。每次射击所需的能量储存在快速放电发生器内；这个装置占据武器内部机构的大部分空间，也负责调节光束功率，以防过载、提高可靠性。',7:'可充电能量弹匣为放电发生器供能。它们通常采用高效的液态金属核心，大小和容量依用途而异。激光枪和激光手枪使用的轻型内置能量弹匣平均可供射击40次；激光炮所用的大型箱式能量单元，则为保持最高输出效率，通常每射击一次就要更换。高功率能量弹匣又称“热射”弹匣，能提供更强的单发能量，但射击次数较少，对枪管负荷更大，也更难重新充能。',9:'多数世界会利用本地材料制造各具特色的激光武器，并加入独有部件，例如为能量弹匣充电的太阳能转换器或不同类型的光学瞄准镜。这些武器既有华丽精巧、手工打造的决斗手枪，也有配发帝国卫队的坚固制式装备。',11:'某些罕见的帝国重型激光武器制造时需要使用普里马塔晶体，但底稿未列明具体型号。这种晶体会发出红光，价格昂贵且供不应求，卖给合适的买家便能获利丰厚。',25:'Hotshot Marksman Rifle 热射射手步枪',26:'Las Fusil (Assumed to be laser.) 激光狙击枪（底稿推定属于激光武器）',38:'Proteus Las Lance 普罗透斯激光光矛',39:'Snub-Nosed Las 短管激光枪',44:'Las-Ripper 激光撕裂炮',47:'Rapier Laser Destroyer 细剑激光毁灭炮',49:'Neutron Laser Projector 中子激光投射炮',50:'Arachnus Blaze Cannon 阿拉克纳斯爆裂炮',51:'Arachnus Storm Cannon 阿拉克纳斯风暴炮',52:'Arachnus Magna-Blaze Cannon 阿拉克纳斯巨型爆裂炮',53:'Corve Las-Pulser 科尔夫激光脉冲炮',54:'Arachnus Heavy Lascannon 阿拉克纳斯重型激光炮',57:'Turbo-laser Destructor 涡轮激光破坏炮',69:'Weapons Batteries 舰炮组',77:'灵族采用以灵能培育的晶体，以及更高效的发电、能量传输系统，因此其激光武器比帝国同类产品更省能量、更精准，也更强大。许多灵族欣赏这类武器的优雅，并以掌控光本身为傲。',95:'Weapons Batteries 舰炮组',97:'Orks 欧克'},notes={7:'能量弹匣容量按所给总述保留；与各型号条目的差异不擅自归一。',11:'Prismata此处为晶体名，与862同名星系不认定相关。',26:'保留本篇分类中的推定措辞；1310单独条目直接称激光武器，体现不同来源描述。',39:'Snub-Nosed指枪身或枪管短，不是翘鼻。',53:'Corve为专名，暂音译科尔夫，不解作轨道。'},terms=[('Laser Weapon','激光武器'),('Prismata Crystals','普里马塔晶体'),('Proteus Las Lance','普罗透斯激光光矛'),('Snub-Nosed Las','短管激光枪'),('Las-Ripper','激光撕裂炮'),('Corve Las-Pulser','科尔夫激光脉冲炮'),('Arachnus Blaze Cannon','阿拉克纳斯爆裂炮'),('Arachnus Storm Cannon','阿拉克纳斯风暴炮'),('Arachnus Magna-Blaze Cannon','阿拉克纳斯巨型爆裂炮'),('Arachnus Heavy Lascannon','阿拉克纳斯重型激光炮'),('Sollex Heavy Lascannon','索莱克斯重型激光炮'),('Turbo-laser Destructor','涡轮激光破坏炮'),('Weapons Batteries','舰炮组')],additions={101:'心脏终结者（Da Heart Stoppa）。'})
save(1309,{6:'激光切割枪最初是切开装甲舱壁和致密矿石的工业工具，利用扰乱场辅助的短程激光弧进行切割。后来它被用于战争，既能在攻城时破开敌方工事，必要时也可成为杀伤力惊人的近战武器。'},terms=[('Lascutter','激光切割枪')])
save(1310,{2:'激光狙击枪是星际战士歼灭者使用的狙击武器，属于激光兵器。它是一种远程步枪，每次射击后都需要短暂充能。'},terms=[('Las Fusil','激光狙击枪')])
